<script setup lang="ts">import {computed} from 'vue';import type {PairedReplication} from '../types/domain';import {number,signed} from '../utils/format';const props=defineProps<{rows:PairedReplication[]}>();const span=computed(()=>Math.max(.05,...props.rows.map(r=>Math.abs(r.difference_minutes))));const mid=110;const scale=(v:number)=>v/span.value*88;
</script><template><div class="rep-chart"><svg viewBox="0 0 600 230" aria-label="配对逐次等待差值分钟"><line x1="35" y1="110" x2="585" y2="110" class="axis"/><g><line x1="35" x2="585" y1="22" y2="22" class="grid"/><line x1="35" x2="585" y1="198" y2="198" class="grid"/><text x="0" y="26">{{signed(span,1)}}</text><text x="0" y="114">0</text><text x="0" y="202">{{signed(-span,1)}}</text></g><g v-for="(r,i) in rows" :key="r.replication"><rect v-if="r.difference_minutes>=0" :x="43+i*535/rows.length" :y="mid-scale(r.difference_minutes)" :width="Math.max(2,480/rows.length)" :height="Math.max(1,scale(r.difference_minutes))" class="positive"><title>第{{r.replication}}次：基准{{number(r.baseline_mean_wait_minutes)}} − 候选{{number(r.candidate_mean_wait_minutes)}} = {{signed(r.difference_minutes)}}分钟</title></rect><rect v-else :x="43+i*535/rows.length" :y="mid" :width="Math.max(2,480/rows.length)" :height="Math.max(1,-scale(r.difference_minutes))" class="negative"><title>第{{r.replication}}次：基准{{number(r.baseline_mean_wait_minutes)}} − 候选{{number(r.candidate_mean_wait_minutes)}} = {{signed(r.difference_minutes)}}分钟</title></rect></g><text x="205" y="225">共用同一批到达与服务 · 逐次配对差值 →</text></svg></div></template>
<style scoped>.rep-chart svg{width:100%;height:auto}.axis{stroke:var(--muted);stroke-width:1.4}.grid{stroke:var(--line);stroke-dasharray:3 4;stroke-width:1}.rep-chart text{font-family:'Noto Sans SC';font-size:10px;fill:var(--muted)}.positive{fill:var(--green);opacity:.85}.negative{fill:var(--orange);opacity:.85}</style>
